// Code node "Verify signed payload" (run once for all items).
//
// The Webhook node has already checked the token's HS256 signature and expiry against
// the "AIOps webhook signature" credential. This node checks what it cannot: that the
// token was issued for this audience, for exactly this payload (its SHA-256 is a claim),
// and for this notification and incident. A token captured in transit is therefore
// useless with any other body, and it expires within minutes.
const crypto = require('crypto');

const ISSUER = 'aiops-engine';
const AUDIENCE = 'aiops-n8n';
const PAYLOAD_VERSION = 1;
const MAX_PAYLOAD_CHARS = 262144;

const request = $('Incident webhook').first().json;
const claims = request.jwtPayload || {};
const raw = request.body ? request.body.payload : undefined;

function reject(reason) {
  return [{ json: { valid: false, reason } }];
}

if (typeof raw !== 'string' || raw.length === 0) {
  return reject('body.payload must be a non-empty JSON string');
}
if (raw.length > MAX_PAYLOAD_CHARS) {
  return reject('payload is too large');
}
if (claims.iss !== ISSUER || claims.aud !== AUDIENCE) {
  return reject('the token has an unexpected issuer or audience');
}
// The hash is part of the signed token, so a plain comparison is enough: without the
// signing key nobody can obtain a token for a different hash.
const digest = crypto.createHash('sha256').update(raw, 'utf8').digest('hex');
if (digest !== claims.payload_sha256) {
  return reject('the payload does not match the token');
}

let data;
try {
  data = JSON.parse(raw);
} catch (error) {
  return reject('the payload is not valid JSON');
}
if (data.version !== PAYLOAD_VERSION) {
  return reject(`unsupported payload version ${data.version}`);
}
if (!data.notification || data.notification.id !== claims.jti) {
  return reject('the payload is for another notification');
}
if (!data.incident || data.incident.id !== claims.sub) {
  return reject('the payload is for another incident');
}
return [{ json: { valid: true, ...data } }];

// Code node "Format message" (run once for all items).
//
// Picks the route and builds the Telegram message (HTML parse mode). Every value from
// the payload is escaped: alert labels, log quotes and model output can contain
// anything, including markup meant to fake a message or hide a link.
//
// Routes (the Switch node after this one sends each to its own branch):
//   page      critical and firing, not flapping: a message with sound. The engine sends
//             these at once, before any analysis, as their own message kind ("page")
//   reply     the analysis that follows a page: silent, a reply to the page in the chat
//   quiet     any other critical or warning (flapping, resolved): a silent message
//   suppress  info and everything else: recorded, not sent
const MAX_LENGTH = 4096; // Telegram's limit for one message
const LABELS = ['compose_project', 'compose_service', 'container', 'service', 'instance', 'job'];
const ICONS = { critical: '🔴', warning: '🟠', info: '🔵' };

const { notification, incident, analysis } = $('Verify signed payload').first().json;

function escape(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

// Shorten before escaping, so an entity is never cut in half.
function clip(value, max) {
  const text = String(value ?? '').trim();
  return text.length > max ? `${text.slice(0, max - 1)}…` : text;
}

function route() {
  if (notification.kind === 'page') return 'page';
  if (notification.follows_page) {
    // Without the page's message ID (its delivery failed) there is nothing to reply to.
    return notification.reply_to_message_id ? 'reply' : 'quiet';
  }
  const severity = incident.severity;
  if (severity === 'critical' && incident.status === 'firing' && !incident.flapping) {
    return 'page';
  }
  if (severity === 'critical' || severity === 'warning') {
    return 'quiet';
  }
  return 'suppress';
}

function clock(iso) {
  return iso ? `${iso.slice(0, 10)} ${iso.slice(11, 16)} UTC` : 'unknown';
}

function duration(fromIso, toIso) {
  const seconds = Math.max(0, Math.round((Date.parse(toIso) - Date.parse(fromIso)) / 1000));
  if (Number.isNaN(seconds)) return 'unknown';
  if (seconds < 120) return `${seconds} s`;
  if (seconds < 7200) return `${Math.round(seconds / 60)} min`;
  return `${(seconds / 3600).toFixed(1)} h`;
}

function header() {
  const resolved = incident.status === 'resolved';
  const icon = resolved ? '✅' : ICONS[incident.severity] || '⚪';
  const state = resolved ? 'RESOLVED' : String(incident.severity || 'unknown').toUpperCase();
  const lines = [`${icon} <b>${escape(state)}</b> · <b>${escape(clip(incident.alertname, 120))}</b>`];
  const annotations = incident.annotations || {};
  if (annotations.summary) lines.push(`<i>${escape(clip(annotations.summary, 300))}</i>`);
  const labels = incident.labels || {};
  const where = LABELS.filter((key) => labels[key])
    .slice(0, 4)
    .map((key) => `${escape(key)}=<code>${escape(clip(labels[key], 80))}</code>`);
  if (where.length) lines.push(where.join(' · '));
  let when = `Started ${clock(incident.starts_at)}`;
  if (resolved && incident.resolved_at) {
    when += `, resolved after ${duration(incident.starts_at, incident.resolved_at)}`;
  }
  lines.push(when);
  if (incident.flapping) lines.push('⚠️ Flapping: this alert keeps firing and resolving.');
  return lines.join('\n');
}

// Sections in order of importance: the last ones are dropped first when too long.
function analysisSections() {
  if (!analysis || analysis.status === 'skipped' || analysis.status === 'pending') return [];
  if (analysis.status === 'failed') {
    return [`<i>No analysis: ${escape(clip(analysis.reason || 'unknown reason', 300))}</i>`];
  }
  const source = [analysis.provider, analysis.model].filter(Boolean).join(' ');
  const sections = [
    `<b>Probable cause</b> (${escape(analysis.confidence || 'unknown')} confidence, ` +
      `${escape(source)})\n${escape(clip(analysis.probable_cause || analysis.summary, 1200))}`,
  ];
  const commands = (analysis.suggested_commands || []).slice(0, 6);
  if (commands.length) {
    const block = commands.map((item) => escape(clip(item.command, 200))).join('\n');
    sections.push(`<b>Read-only checks</b>\n<pre>${block}</pre>`);
  }
  const evidence = (analysis.evidence || []).slice(0, 3);
  if (evidence.length) {
    const quotes = evidence.map((item) => `• <code>${escape(clip(item.quote, 200))}</code>`);
    sections.push(`<b>Evidence</b>\n${quotes.join('\n')}`);
  }
  const steps = (analysis.next_steps || []).slice(0, 4);
  if (steps.length) {
    const list = steps.map((step, index) => `${index + 1}. ${escape(clip(step, 200))}`);
    sections.push(`<b>Next steps</b>\n${list.join('\n')}`);
  }
  if (analysis.commands_rejected > 0) {
    sections.push(`<i>${analysis.commands_rejected} suggested command(s) withheld: not read-only.</i>`);
  }
  return sections;
}

// The analysis that follows a page: the page already said what fires and where.
function followUpHeader() {
  const lines = [`🔎 <b>Analysis</b> · <b>${escape(clip(incident.alertname, 120))}</b>`];
  if (incident.status === 'resolved' && incident.resolved_at) {
    lines.push(`Resolved after ${duration(incident.starts_at, incident.resolved_at)}`);
  } else {
    lines.push(`Still firing since ${clock(incident.starts_at)}`);
  }
  return lines.join('\n');
}

function message() {
  const footer = `Incident <code>${escape(incident.id)}</code>`;
  if (notification.kind === 'page') {
    return [header(), '<i>Analysis follows.</i>', footer].join('\n\n');
  }
  const top = notification.follows_page ? followUpHeader() : header();
  // The all-clear is short; the firing message carries the analysis.
  const sections = notification.kind === 'resolved' ? [] : analysisSections();
  // Header and footer are clipped field by field and stay far below the limit.
  let text = [top, ...sections, footer].join('\n\n');
  while (text.length > MAX_LENGTH && sections.length) {
    sections.pop();
    text = [top, ...sections, footer].join('\n\n');
  }
  return text;
}

const chosen = route();
return [
  {
    json: {
      route: chosen,
      disable_notification: chosen !== 'page',
      reply_to_message_id: chosen === 'reply' ? Number(notification.reply_to_message_id) : null,
      text: message(),
      notification_id: notification.id,
      incident_id: incident.id,
      kind: notification.kind,
    },
  },
];

// Code node "Delivery outcome" (run once for each item).
//
// Turns whatever reached this node into one report for the engine: a Telegram
// response (delivered, with its message_id), a Telegram node's error output after its
// retries (failed, with the reason), or the Switch's "suppress" branch (suppressed).
const MAX_ERROR_CHARS = 500;

const message = $('Format message').item.json;
const input = $json;

function describe(error) {
  if (!error) return 'unknown error';
  if (typeof error === 'string') return error;
  const parts = [error.message, error.description].filter(Boolean);
  return parts.length ? [...new Set(parts)].join(': ') : JSON.stringify(error);
}

let report;
if (message.route === 'suppress') {
  report = { status: 'suppressed' };
} else {
  const sent = input.result && input.result.message_id !== undefined ? input.result : input;
  if (sent && sent.message_id !== undefined && !input.error) {
    report = { status: 'delivered', channel: 'telegram', channel_message_id: String(sent.message_id) };
  } else {
    report = {
      status: 'failed',
      channel: 'telegram',
      error: describe(input.error).slice(0, MAX_ERROR_CHARS),
    };
  }
}

return {
  json: {
    notification_id: message.notification_id,
    report: { ...report, route: message.route, execution_id: String($execution.id) },
  },
};
